DROP TABLE IF EXISTS `tb_pagos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_pagos` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `pedido_ID` int unsigned NOT NULL,
  `metodo_pago_ID` int unsigned NOT NULL,
  `importe` decimal(12,2) NOT NULL,
  `moneda` char(3) NOT NULL DEFAULT 'MXN',
  `proveedor` varchar(80) DEFAULT NULL,
  `referencia_proveedor` varchar(150) DEFAULT NULL,
  `estado` enum('Pendiente','Autorizado','Pagado','Fallido','Reembolsado','Reembolso_parcial') NOT NULL DEFAULT 'Pendiente',
  `fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ultima_actualizacion` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `uk_pago_proveedor_referencia` (`proveedor`,`referencia_proveedor`),
  KEY `idx_pagos_pedido` (`pedido_ID`),
  KEY `idx_pagos_metodo` (`metodo_pago_ID`),
  CONSTRAINT `fk_pagos_metodo` FOREIGN KEY (`metodo_pago_ID`) REFERENCES `tbc_metodos_pago` (`ID`),
  CONSTRAINT `fk_pagos_pedido` FOREIGN KEY (`pedido_ID`) REFERENCES `tb_pedidos` (`ID`),
  CONSTRAINT `chk_pagos_importe` CHECK ((`importe` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
